INSERT INTO trechos (id, texto, publico, macronarrativa, pauta, tipo, forca, link, pagina) VALUES ('D01-TR-042-jov', 'O dinheiro aparece como falta ou sonho distante, mas deve ser narrado como retomada de controle.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '20'), ('D01-TR-052-jov', 'A equação tempo igual a dinheiro pesa no cotidiano.', 'jovens', 'dinheiro no bolso', 'jornada de trabalho', 'achado', 'indício', NULL, '22'), ('D01-TR-109', 'O valor simbólico do dinheiro não é desejo de consumo, é busca por previsibilidade: capacidade de fechar o mês.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '41'), ('D03-TR-006-jov', '5,4% da população obteve renda nos últimos doze meses com alguma atividade online, como vendas, links de afiliados, revendas, visualização remunerada de vídeos ou atuação como ponto de coleta de lojas online.', 'jovens', 'dinheiro no bolso', 'renda e sustento', 'achado', 'indício', NULL, '15'), ('D03-TR-074-jov', 'O combate às desigualdades e privilégios recebe 21,1% de avaliação ótima ou boa e 38,2% ruim ou péssima.', 'jovens', 'dinheiro no bolso', 'desigualdade', 'achado', 'indício', NULL, '73'), ('D03-TR-075-jov', 'Custo de vida, poder de compra e economia é a área com pior avaliação da gestão federal: 16,0% ótima ou boa e 53,7% ruim ou péssima.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '73'), ('D03-TR-080-jov', 'A isenção do Imposto de Renda para quem ganha até 5 mil reais é conhecida por 72,4%, com avaliação de 68,9% ótima ou boa e 11,4% ruim ou péssima.', 'jovens', 'dinheiro no bolso', 'impostos', 'achado', 'indício', NULL, '76'), ('D03-TR-083-jov', 'O Desenrola, para renegociar dívidas, é conhecido por 62,1%, com avaliação de 67,9% ótima ou boa e 9,7% ruim ou péssima.', 'jovens', 'dinheiro no bolso', 'endividamento e crédito', 'achado', 'indício', NULL, '76'), ('D03-TR-089-jov', 'No Nordeste, o Pé-de-Meia é o programa federal mais conhecido da lista (90,1%), acima da média nacional (81,0%), com avaliação de 69,3% ótima ou boa.', 'jovens', 'dinheiro no bolso', 'educação', 'achado', 'indício', NULL, '78'), ('D04-TR-004', 'Na macronarrativa Dinheiro no Bolso, a narrativa central para o público jovem vai do começo de vida no sufoco à margem para planejar o amanhã.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'achado', 'indício', NULL, '8'), ('D04-TR-005', 'Para o jovem, o dinheiro não aparece como consumo ou ascensão, mas como objeto que amplia o poder fazer: pagar, circular, estudar, ajudar em casa, sair da dívida e manter o futuro aberto.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'achado', 'indício', NULL, '8'), ('D04-TR-013', 'Para jovens de classes C/D, o dinheiro é a margem entre uma vida que começa e uma vida que já parece travada.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'achado', 'indício', NULL, '10'), ('D04-TR-015', 'O dinheiro reduz improviso: ajuda a manter curso, pagar transporte, comprar o básico, ajudar a família e sustentar planos instáveis.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '10'), ('D04-TR-016', 'O futuro existe, mas chega como pressão: casa, carreira, independência, família e estabilidade dependem de dinheiro e previsibilidade.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'achado', 'indício', NULL, '10'), ('D04-TR-021', 'Na escuta digital, o dinheiro aparece ligado a custo de vida, impostos, dívidas e benefícios, com a sensação de que trabalhar não garante sobra.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '10'), ('D04-TR-022', 'Na escuta digital, ganham força relatos de dívida, corte de gastos, organização financeira e reconstrução depois do aperto, enquanto a ostentação perde centralidade.', 'jovens', 'dinheiro no bolso', 'endividamento e crédito', 'achado', 'indício', NULL, '10'), ('D04-TR-023', 'Na escuta digital, o endividamento aparece com angústia, desespero e busca por acolhimento.', 'jovens', 'dinheiro no bolso', 'endividamento e crédito', 'achado', 'indício', NULL, '10'), ('D04-TR-024', 'Sem resposta pública percebida para o endividamento, fé e ajuda informal ocupam o lugar de acolhimento.', 'jovens', 'dinheiro no bolso', 'endividamento e crédito', 'achado', 'indício', NULL, '10'), ('D04-TR-028', 'A macronarrativa Dinheiro no Bolso organiza a tensão entre juventude comprimida, aperto material e futuro ainda em construção.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'achado', 'indício', NULL, '11'), ('D04-TR-029', 'Na macronarrativa Dinheiro no Bolso, "juventude comprimida" é isotopia reiterada: a vida adulta chegou cedo, mas a trajetória ainda está em formação.', 'jovens', 'dinheiro no bolso', 'condição juvenil', 'achado', 'forte', NULL, '11'), ('D04-TR-030', 'Na macronarrativa Dinheiro no Bolso, "aperto material e vida que precisa fechar" é isotopia reiterada: o dinheiro é vivido como cálculo, falta, dívida e tentativa de reorganização.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'achado', 'forte', NULL, '11'), ('D04-TR-031', 'Na macronarrativa Dinheiro no Bolso, "margem para continuar e projetar futuro" é isotopia reiterada: a melhora aparece como respiro possível, não como luxo.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'achado', 'forte', NULL, '11'), ('D04-TR-032', 'O dinheiro importa porque define se o jovem consegue estudar, circular, trabalhar, ajudar em casa e começar a vida sem já se sentir travado.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'achado', 'indício', NULL, '11'), ('D04-TR-033', 'Custo de vida, salário curto, contas, impostos, juros e endividamento estruturam a sensação de que trabalhar nem sempre basta para ter sobra ou previsibilidade.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '11'), ('D04-TR-034', 'O valor simbólico do dinheiro está em reduzir improviso, aliviar ansiedade e permitir pequenos planos: manter o curso, pagar passagem, renegociar dívida, guardar um pouco, sair sem culpa.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'achado', 'indício', NULL, '11'), ('D04-TR-038', 'Os jovens desse perfil já vivem cobranças de adulto, mas ainda precisam de margem para construir trajetória, autonomia e futuro.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'achado', 'indício', NULL, '12'), ('D04-TR-039', 'A macronarrativa Dinheiro no Bolso organiza a passagem de uma juventude que começa sob pressão para uma juventude com alguma margem de ação.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'achado', 'indício', NULL, '13'), ('D04-TR-040', 'O sujeito jovem não busca apenas "mais dinheiro", mas condições mínimas para continuar construindo a própria vida sem que tudo vire urgência.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'achado', 'indício', NULL, '13'), ('D04-TR-041', 'O dinheiro não leva do "pobre" ao "rico"; leva do sufoco à margem.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'achado', 'indício', NULL, '13'), ('D04-TR-042', 'O percurso narrativo do dinheiro vai do aperto (disjunção: sem sobra, sem previsibilidade, com dívida e sensação de que trabalhar não basta) à reorganização (transformação: benefício, informação, oportunidade, renegociação, apoio e política pública como caminho prático) e à margem (conjunção: estudar, pagar, circular, ajudar, respirar e projetar futuro com menos ansiedade). Nesse percurso, o jovem passa de distante de recursos e possibilidades a indivíduo que vislumbra um futuro com mais confiança.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'achado', 'indício', NULL, '13'), ('D04-TR-043', 'A especificidade jovem está na sobreposição entre vida em construção e pressão adulta: curso, primeiro emprego, transporte, internet, ajuda em casa, contas e planos ainda instáveis.', 'jovens', 'dinheiro no bolso', 'condição juvenil', 'achado', 'indício', NULL, '14'), ('D04-TR-045', 'A dívida aparece como vergonha, angústia e vida bloqueada. Para jovens, pesa ainda mais porque compromete crédito, autonomia e planos logo no início da trajetória.', 'jovens', 'dinheiro no bolso', 'endividamento e crédito', 'achado', 'indício', NULL, '14'), ('D04-TR-051', 'Na narrativa do dinheiro como margem, o jovem é sujeito em construção: trabalha, estuda, ajuda ou sustenta a casa, tenta circular, sustentar planos e ganhar autonomia.', 'jovens', 'dinheiro no bolso', 'condição juvenil', 'achado', 'indício', NULL, '15'), ('D04-TR-053', 'Transformação narrativa em jogo: no estado inicial, a vida já cobra como adulta e contas, estudo, trabalho, família e futuro chegam juntos, com pouca margem de erro; o dinheiro entra como condição de continuidade, reduzindo improviso, organizando o básico e abrindo espaço mental para planejar; no estado final, o jovem consegue seguir estudando, trabalhando, circulando e projetando futuro sem sentir que a vida já está bloqueada.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'achado', 'indício', NULL, '15'), ('D04-TR-054', 'A dívida não é apenas um problema financeiro: para o jovem, ela antecipa bloqueios e reduz a sensação de que ainda dá para construir caminho.', 'jovens', 'dinheiro no bolso', 'endividamento e crédito', 'achado', 'indício', NULL, '16'), ('D04-TR-055', 'Na narrativa da saída da dívida, o jovem é sujeito em risco de travamento: tenta pagar, renegociar, evitar juros, limpar o nome e recuperar autonomia para seguir planejando.', 'jovens', 'dinheiro no bolso', 'endividamento e crédito', 'achado', 'indício', NULL, '16'), ('D04-TR-057', 'Transformação narrativa em jogo: no estado inicial, o jovem começa a trajetória com dívida, nome sujo, juros, vergonha ou sensação de que perdeu o controle antes mesmo de se estabilizar; a informação e os caminhos de renegociação entram como instrumentos para reduzir o sufoco e reabrir possibilidades; no estado final, a dívida deixa de ser sentença e vira etapa administrável, com recuperação de fôlego, crédito, confiança e capacidade de projetar futuro.', 'jovens', 'dinheiro no bolso', 'endividamento e crédito', 'achado', 'indício', NULL, '16'), ('D04-TR-059', 'Na narrativa da informação financeira, o jovem é sujeito que aprende no fluxo: recebe informação pelo feed, compara relatos, busca confirmação quando precisa decidir e valoriza conteúdos que explicam sem enrolar.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'achado', 'indício', NULL, '17'), ('D04-TR-061', 'Transformação narrativa em jogo: no estado inicial, a informação sobre dinheiro, benefício, imposto ou dívida chega fragmentada, confusa ou com cara de propaganda; a comunicação traduz o tema em caminho prático, mostrando o que é, quem acessa, como funciona, onde checar e que diferença faz; no estado final, o jovem ganha mais controle para decidir, buscar direito, evitar armadilha, compartilhar informação segura e planejar com menos ansiedade.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'achado', 'indício', NULL, '17'), ('D04-TR-068-din', 'O repertório digital jovem traduz crítica social por humor, trend e experiência concreta, mais do que por explicação institucional longa.', 'jovens', 'dinheiro no bolso', 'comunicação e linguagem', 'achado', 'indício', NULL, '19'), ('D04-TR-197-din', 'A força das macronarrativas está em transformar pressão cotidiana em informação, proteção e horizonte possível.', 'jovens', 'dinheiro no bolso', 'comunicação e linguagem', 'achado', 'indício', NULL, '40'), ('D06-TR-009', 'Dinheiro importa porque reduz improviso: permite estudar, circular, ajudar em casa, pagar contas e sustentar planos.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'achado', 'forte', NULL, '7'), ('D06-TR-010', 'Dinheiro não é lido como promessa de consumo, e sim como condição para que a vida não desande.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '7'), ('D06-TR-085', 'Dinheiro no bolso convence quando significa respirar no fim do mês.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'achado', 'forte', NULL, '33'), ('D06-TR-086', 'O território aparece com força, mas menos como "dinheiro" em si e mais como capacidade de manter a vida funcionando. Quando os jovens falam de melhorar de vida, falam de mercado, remédio, gasolina, estudo, casa, salário e possibilidade de ajudar a família.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '33'), ('D06-TR-141-din', 'Explicar quem decide transforma desconfiança em possibilidade de cobrança.', 'jovens', 'dinheiro no bolso', 'comunicação e linguagem', 'achado', 'indício', NULL, '40'), ('D06-TR-143-din', 'Há uma lacuna clara: muitos sabem que política importa, mas não necessariamente sabem onde cada decisão acontece.', 'jovens', 'dinheiro no bolso', 'comunicação e linguagem', 'achado', 'indício', NULL, '40'), ('D07-TR-001-jov', 'Entre os participantes deste estudo, custo de vida, poder de compra e economia é a área de maior peso na formação da avaliação pública de desempenho governamental.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '3'), ('D07-TR-018-jov', 'Custo de vida concentra o maior impacto isolado sobre a avaliação pública de desempenho, com magnitude cerca de duas vezes a da segunda área da lista.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '5'), ('D07-TR-028-jov', 'Na Região Sul, o peso de custo de vida na avaliação de desempenho governamental é substancialmente superior ao observado no conjunto do país.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '6'), ('D07-TR-045-jov', 'Na Região Norte, o peso de custo de vida na avaliação de desempenho governamental é substancialmente superior ao observado no conjunto do país.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'achado', 'indício', NULL, '10'), ('D04-TR-202', 'Prometer prosperidade genérica afasta: aproxima a reorganização possível, com pequenas viradas que mostram controle, alívio e continuidade.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'afasta', NULL, NULL, '10'), ('D04-TR-203', 'Ostentação e consumo como imagem de dinheiro afastam: a ostentação perdeu centralidade, e dinheiro vale como redução de risco e previsibilidade.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'afasta', NULL, NULL, '10'), ('D04-TR-204', 'Falar de dinheiro só como orçamento adulto afasta: para o jovem, dinheiro é estudar, circular, ajudar em casa e não começar a vida já no sufoco.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'afasta', NULL, NULL, '10'), ('D04-TR-205', 'Narrativa de ascensão social, do "pobre" ao "rico", afasta: o dinheiro que faz sentido leva do sufoco à margem, não à riqueza.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'afasta', NULL, NULL, '13'), ('D04-TR-206', 'Tratar a dívida como culpa individual afasta: a dívida já chega como vergonha e vida bloqueada, e o que aproxima é mostrar caminhos concretos de renegociação.', 'jovens', 'dinheiro no bolso', 'endividamento e crédito', 'afasta', NULL, NULL, '14'), ('D04-TR-207', 'Conteúdo com cara de propaganda afasta: relatos, tutoriais, bastidores, antes e depois e linguagem direta aproximam mais.', 'jovens', 'dinheiro no bolso', 'comunicação e linguagem', 'afasta', NULL, NULL, '14'), ('D04-TR-208', 'Informação sobre benefício, direito, imposto ou dívida que chega fragmentada ou confusa afasta: precisa dizer o que é, quem acessa, como funciona, onde checar e que diferença faz.', 'jovens', 'dinheiro no bolso', 'informação sobre direitos', 'afasta', NULL, NULL, '17'), ('D04-TR-228-din', 'Infantilizar afasta: esses jovens podem ter trabalho, família e filhos, e precisam ser reconhecidos como jovens sem serem tratados como adolescentes.', 'jovens', 'dinheiro no bolso', 'condição juvenil', 'afasta', NULL, NULL, '40'), ('D04-TR-229-din', 'Cobrar que o jovem resolva sozinho o que é estrutural afasta: ele precisa de informação simples, proteção efetiva e caminhos claros.', 'jovens', 'dinheiro no bolso', 'autonomia e amparo', 'afasta', NULL, NULL, '40'), ('D04-TR-230-din', 'Convocação abstrata afasta: a comunicação precisa começar nos temas que já organizam a rotina, estudo, transporte, consumo, primeiro emprego, escala, família e segurança.', 'jovens', 'dinheiro no bolso', 'comunicação e linguagem', 'afasta', NULL, NULL, '40'), ('D06-TR-159', 'Tratar dinheiro como promessa de consumo afasta: para este público, dinheiro é condição para a vida não desandar, não desejo de compra.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'afasta', NULL, NULL, '7'), ('D06-TR-162-din', 'Falar com um "jovem" abstrato afasta: este público se mede por responsabilidade, tempo curto, dinheiro, família e futuro, e precisa ser tratado como jovem adulto.', 'jovens', 'dinheiro no bolso', 'comunicação e linguagem', 'afasta', NULL, NULL, '10'), ('D06-TR-163-din', 'Reproduzir estereótipos de jovem irresponsável, geração que não quer trabalhar ou gente sem experiência para opinar afasta: a juventude vira marca de suspeita e gera irritação.', 'jovens', 'dinheiro no bolso', 'etarismo', 'afasta', NULL, NULL, '11'), ('D06-TR-165-din', 'Mensagens sobre futuro que soam apenas inspiracionais afastam: futuro crível mostra caminho, condição e proteção.', 'jovens', 'dinheiro no bolso', 'futuro possível', 'afasta', NULL, NULL, '13'), ('D06-TR-167-din', 'Reduzir a comunicação com jovens a "linguagem jovem" afasta: o que aproxima é reconhecer uma juventude encurtada por trabalho, família, medo e necessidade de construir futuro cedo.', 'jovens', 'dinheiro no bolso', 'comunicação e linguagem', 'afasta', NULL, NULL, '15'), ('D06-TR-078', 'Dinheiro no bolso aparece como custo de vida, mercado, remédio, gasolina, salário, estudo e capacidade de fechar o mês; não é desejo de consumo, é busca por previsibilidade. Potencial narrativo alto, desde que fale de vida possível e conecte renda a estudo, casa, família e alívio do aperto.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'contexto', NULL, NULL, '32'), ('D01-TR-030-jov', 'O engajamento nasce de caminho prático, nunca de slogan de superação.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'funciona', NULL, NULL, '17'), ('D01-TR-046-jov', 'Mostrar como um Estado presente pode ajudar no alívio do dia a dia por meio de políticas públicas.', 'jovens', 'dinheiro no bolso', 'atribuição de políticas públicas', 'funciona', NULL, NULL, '21'), ('D01-TR-108', 'Dinheiro no bolso convence quando significa respirar no fim do mês; organiza a tensão entre juventude comprimida, aperto material e futuro ainda em construção.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'funciona', NULL, NULL, '40'), ('D01-TR-110', 'Mostrar que dinheiro no bolso é condição para seguir: pagar o essencial, estudar, circular, ajudar em casa e planejar o futuro sem sentir que ele já está travado.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'funciona', NULL, NULL, '41'), ('D01-TR-111', 'Reconhecer o aperto sem prometer riqueza: sair do sufoco já é conquista.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'funciona', NULL, NULL, '41'), ('D01-TR-112', 'Tirar a dívida da culpa individual: mostrar caminhos de apoio para renegociação e juros.', 'jovens', 'dinheiro no bolso', 'endividamento e crédito', 'funciona', NULL, NULL, '41'), ('D01-TR-113', 'Traduzir benefício, direito e imposto em linguagem simples e verificável.', 'jovens', 'dinheiro no bolso', 'atribuição de políticas públicas', 'funciona', NULL, NULL, '41'), ('D04-TR-006', 'A comunicação sobre dinheiro deve traduzir o tema em continuidade concreta: menos improviso, menos ansiedade e mais condição para organizar a vida que ainda está começando.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'funciona', NULL, NULL, '8'), ('D04-TR-018-din', 'O conteúdo aproxima mais quando vem em formato curto e real: relato, bastidor, tutorial, comparação, antes e depois e dica prática.', 'jovens', 'dinheiro no bolso', 'comunicação e linguagem', 'funciona', NULL, NULL, '10'), ('D04-TR-025', 'A macronarrativa Dinheiro no Bolso precisa falar de vida jovem em construção, não só de orçamento adulto: estudar, circular, ajudar em casa e não começar a vida já no sufoco.', 'jovens', 'dinheiro no bolso', 'condição juvenil', 'funciona', NULL, NULL, '10'), ('D04-TR-026', 'A narrativa deve trocar prosperidade genérica por reorganização possível: pequenas viradas que mostram controle, alívio e continuidade.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'funciona', NULL, NULL, '10'), ('D04-TR-027', 'A comunicação deve mostrar dinheiro como redução de risco: sair do sufoco, evitar juros, entender caminhos e recuperar paz mental para continuar projetando futuro.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'funciona', NULL, NULL, '10'), ('D04-TR-035', 'Figuras que materializam o cuidado com dinheiro: curso, material, transporte, estágio, primeiro emprego, filho, casa, ajuda para a mãe e rolê que cabe no bolso.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'funciona', NULL, NULL, '11'), ('D04-TR-036', 'Figuras do aperto material: mercado, gás, luz, aluguel, boleto, Pix, cartão, Serasa, nome sujo, juros, salário que cai e some e diário das dívidas.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'funciona', NULL, NULL, '11'), ('D04-TR-037', 'Figuras da margem recuperada: sobra no fim do mês, dívida renegociada, passagem garantida, curso pago, reserva pequena, compra planejada e "conseguir chegar lá".', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'funciona', NULL, NULL, '11'), ('D04-TR-044', 'A promessa comunicacional é mostrar que Dinheiro no Bolso é condição para seguir: pagar o essencial, estudar, circular, ajudar em casa e planejar o futuro sem sentir que ele já está travado.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'funciona', NULL, NULL, '14'), ('D04-TR-046', 'Tirar a dívida da culpa individual e mostrar caminhos concretos: renegociar, entender juros, evitar armadilhas e voltar a respirar.', 'jovens', 'dinheiro no bolso', 'endividamento e crédito', 'funciona', NULL, NULL, '14'), ('D04-TR-048-din', 'Relatos, tutoriais, bastidores, antes e depois e linguagem direta aproximam mais do que propaganda.', 'jovens', 'dinheiro no bolso', 'comunicação e linguagem', 'funciona', NULL, NULL, '14'), ('D04-TR-049', 'Fazer da comunicação uma ferramenta prática: explicar benefício, direito, imposto, dívida e oportunidade de modo simples, verificável e compartilhável.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'funciona', NULL, NULL, '14'), ('D04-TR-050', 'A macronarrativa Dinheiro no Bolso deve ser apresentada como margem para organizar o presente e não deixar o futuro travar antes de começar.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'funciona', NULL, NULL, '15'), ('D04-TR-052', 'Mostrar situações concretas de margem: pagar transporte, manter curso, comprar material, ajudar em casa, ter internet e algum respiro no fim do mês.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'funciona', NULL, NULL, '15'), ('D04-TR-056', 'Tirar a dívida da culpa individual e mostrar caminhos concretos: renegociação, educação financeira simples, alerta sobre juros, crédito responsável e apoio para reorganizar a vida.', 'jovens', 'dinheiro no bolso', 'endividamento e crédito', 'funciona', NULL, NULL, '16'), ('D04-TR-058', 'A comunicação de Dinheiro no Bolso precisa ser fácil de entender, checar e aplicar: informação clara transforma benefício, direito, imposto, dívida ou oportunidade em decisão prática.', 'jovens', 'dinheiro no bolso', 'orçamento e planejamento', 'funciona', NULL, NULL, '17'), ('D04-TR-060', 'Usar linguagem direta, formatos curtos e verificáveis: tutorial, passo a passo, antes e depois, print, bastidor, relato real, simulador, checklist e explicação simples do que muda na vida.', 'jovens', 'dinheiro no bolso', 'comunicação e linguagem', 'funciona', NULL, NULL, '17'), ('D04-TR-190-din', 'Comunicar com concretude, linguagem simples, prova verificável e formatos próximos: relato, bastidor, tutorial, antes e depois, humor e checagem.', 'jovens', 'dinheiro no bolso', 'comunicação e linguagem', 'funciona', NULL, NULL, '39'), ('D04-TR-196', 'O desafio não é cobrar que o jovem dê conta de tudo, mas criar condições para que a vida pese menos.', 'jovens', 'dinheiro no bolso', 'condição juvenil', 'funciona', NULL, NULL, '40'), ('D04-TR-199-din', 'Transformar políticas em condição de vida melhor: dinheiro, trabalho e engajamento precisam aparecer como suporte concreto, como pagar o básico, sair da dívida, trabalhar com dignidade, entender direitos, checar informações e cobrar resultados.', 'jovens', 'dinheiro no bolso', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D04-TR-200-din', 'Partir da vida real, não da convocação abstrata: a comunicação deve começar nos temas que já organizam a rotina, como estudo, transporte, consumo, primeiro emprego, escala, Pix, taxa das blusinhas, família, segurança, voto e futuro.', 'jovens', 'dinheiro no bolso', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D04-TR-201-din', 'Dar competência sem transferir responsabilidade: o jovem não precisa ser cobrado a resolver sozinho o que é estrutural, e sim de informação simples, proteção efetiva e caminhos claros para viver melhor, decidir com mais segurança e voltar a vislumbrar futuro.', 'jovens', 'dinheiro no bolso', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D06-TR-003-din', 'As narrativas de maior força são as que partem da vida concreta.', 'jovens', 'dinheiro no bolso', 'comunicação e linguagem', 'funciona', NULL, NULL, '7'), ('D06-TR-087', '"Dinheiro no bolso" ganha aderência quando vira dinheiro que permite estudar, se deslocar, comprar o básico, aliviar dívida, ter algum lazer e não viver sempre no limite; a expressão precisa ser menos slogan e mais situação concreta.', 'jovens', 'dinheiro no bolso', 'custo de vida', 'funciona', NULL, NULL, '33'), ('D06-TR-142-din', 'Responsabilização é menos um território emocional e mais uma chave de tradução: ganha força quando explica por que o voto para Legislativo, Senado e Congresso afeta salário, escala, direitos, internet, transporte, segurança e programas.', 'jovens', 'dinheiro no bolso', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D06-TR-144-din', 'Quando a comunicação traduz quem aprova, quem bloqueia, quem executa e quem responde, a política deixa de parecer um bloco distante.', 'jovens', 'dinheiro no bolso', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D06-TR-155-din', 'Proteção do trabalhador, dinheiro no bolso e proteção da família são os territórios de maior lastro espontâneo — já estão na vida dos jovens antes da política aparecer, por isso devem funcionar como portas de entrada principais.', 'jovens', 'dinheiro no bolso', 'comunicação e linguagem', 'funciona', NULL, NULL, '42'), ('D06-TR-156-din', 'Brasil Core e Engajamento Cívico têm potencial, mas precisam de prova: Brasil precisa aparecer como cultura vivida e soberania concreta; Engajamento precisa mostrar onde a voz jovem produz efeito.', 'jovens', 'dinheiro no bolso', 'comunicação e linguagem', 'funciona', NULL, NULL, '42'), ('D06-TR-158-din', 'Responsabilização e Senado é a principal ponte pedagógica: não mobiliza sozinho, mas ajuda a transformar temas concretos em escolha eleitoral, mostrando quem aprova, quem trava, quem amplia e quem ameaça.', 'jovens', 'dinheiro no bolso', 'comunicação e linguagem', 'funciona', NULL, NULL, '42'), ('D06-TR-089', '“Realmente hoje em dia é o custo de vida mesmo. A gente está vivendo o básico e já está complicado.”', 'jovens', 'dinheiro no bolso', 'custo de vida', 'verbatim', NULL, NULL, '33'), ('D06-TR-090', '“Mercado, remédio, gasolina. Está complicado hoje em dia. A gente está vivendo o básico dos básicos.”', 'jovens', 'dinheiro no bolso', 'custo de vida', 'verbatim', NULL, NULL, '33'), ('D06-TR-091', '“Para manter meu curso, comprar meus materiais, manter a escola, manter tudo funcionando, eu precisei iniciar no mundo gastronômico.”', 'jovens', 'dinheiro no bolso', 'custo de vida', 'verbatim', NULL, NULL, '33'), ('D06-TR-146-din', '“São eles que discutem a pauta. São eles que aprovam e desaprovam. Então a nossa vida passa na mão dos deputados.”', 'jovens', 'dinheiro no bolso', 'comunicação e linguagem', 'verbatim', NULL, NULL, '40'), ('D06-TR-148-din', '“As pessoas votam para senador, para deputado, mas não sabem o que fazem. Acham que o importante é só o presidente e o governador.”', 'jovens', 'dinheiro no bolso', 'comunicação e linguagem', 'verbatim', NULL, NULL, '40'), ('D06-TR-149-din', '“Seria interessante se ensinassem na escola a atribuição de cada um.”', 'jovens', 'dinheiro no bolso', 'comunicação e linguagem', 'verbatim', NULL, NULL, '40'), ('D01-TR-103-jov', 'A vida chegou cedo demais, mas eles não deixaram de ser jovens: a juventude aparece menos como fase livre e mais como identidade comprimida por responsabilidades adultas.', 'jovens', 'trabalho digno', 'juventude e trabalho', 'achado', 'indício', NULL, '38'), ('D01-TR-104-jov', 'A rotina não é só corrida, ela consome o espaço de experimentar a juventude: trabalho, estudo, deslocamento e casa ocupam a maior parte da rotina, e o tempo livre aparece menos como lazer e mais como recuperação física e mental.', 'jovens', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '38'), ('D01-TR-114', 'Proteger o trabalhador não é evitar esforço: é impedir que o trabalho consuma a vida antes que ela se estabilize. É o território mais forte para os jovens.', 'jovens', 'trabalho digno', 'juventude e trabalho', 'achado', 'indício', NULL, '42'), ('D01-TR-115', 'O trabalho organiza quase todos os outros temas para os jovens: dinheiro, cansaço, família, estudo, saúde mental, futuro e voto.', 'jovens', 'trabalho digno', 'juventude e trabalho', 'achado', 'indício', NULL, '43'), ('D01-TR-116', 'Para homens jovens, o tema do trabalho aparece conectado à provisão e à responsabilidade.', 'jovens', 'trabalho digno', 'juventude e trabalho', 'achado', 'indício', NULL, '44'), ('D01-TR-117', 'Para mulheres jovens, ao trabalho somam-se a luta por credibilidade, o cansaço e a desigualdade no ambiente de trabalho.', 'jovens', 'trabalho digno', 'gênero e trabalho', 'achado', 'indício', NULL, '44'), ('D01-TR-118', 'O valor simbólico da trabalho e direitos desloca o jovem do estigma de "não quer trabalhar" para o reconhecimento de que deseja trabalhar com dignidade, descanso, saúde e perspectiva.', 'jovens', 'trabalho digno', 'juventude e trabalho', 'achado', 'indício', NULL, '45'), ('D03-TR-010-jov', 'Carreira, trabalho e sustento é citado por 6,1% como opção mais importante na vida hoje e por 17,9% somando primeira e segunda opções.', 'jovens', 'trabalho digno', 'renda e sustento', 'achado', 'indício', NULL, '16'), ('D03-TR-081-jov', 'O fim da escala 6 por 1 é conhecido por 67,3%, com avaliação de 59,3% ótima ou boa e 18,8% ruim ou péssima.', 'jovens', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '76'), ('D04-TR-001', 'A especificidade do perfil jovem está na sobreposição entre responsabilidade adulta precoce e repertório geracional jovem. Há trabalho, estudo, ajuda em casa, cuidado de filhos ou familiares e preocupação com renda, segurança e futuro, e por isso as dores desse público podem se parecer com as de adultos de classes C/D, sem que ele deva ser lido como adulto.', 'jovens', 'trabalho digno', 'condição juvenil', 'achado', 'indício', NULL, '7'), ('D04-TR-002', 'Muitos jovens já carregam responsabilidades associadas à vida adulta, inclusive trabalho, família, filhos ou contribuição em casa.', 'jovens', 'trabalho digno', 'condição juvenil', 'achado', 'indício', NULL, '7'), ('D04-TR-007', 'Na macronarrativa Proteção ao Trabalhador, a narrativa central para o público jovem vai do trabalho que ocupa tudo ao trabalho que cabe na vida.', 'jovens', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '8'), ('D04-TR-008', 'A transformação narrativa desloca o jovem do estigma de que "não quer trabalhar" para o reconhecimento de que deseja trabalhar com dignidade, descanso, saúde e perspectiva.', 'jovens', 'trabalho digno', 'reconhecimento do trabalho', 'achado', 'indício', NULL, '8'), ('D04-TR-062', 'Para o público jovem, proteção não significa evitar esforço: significa impedir que o trabalho consuma a vida antes que ela se estabilize.', 'jovens', 'trabalho digno', 'reconhecimento do trabalho', 'achado', 'indício', NULL, '19'), ('D04-TR-063', 'Muitos jovens já vivem responsabilidades adultas, como trabalho, renda, família, filhos ou ajuda em casa, mas ainda estão construindo autonomia, estabilidade e trajetória.', 'jovens', 'trabalho digno', 'condição juvenil', 'achado', 'indício', NULL, '19'), ('D04-TR-064', 'O trabalho tem valor para o jovem porque permite autonomia: ganhar dinheiro, sair da dependência, ajudar em casa e começar a construir a própria vida.', 'jovens', 'trabalho digno', 'reconhecimento do trabalho', 'achado', 'indício', NULL, '19'), ('D04-TR-065', 'A diferença geracional não está em rejeitar o trabalho, mas em questionar um modelo em que o esforço não garante recompensa, tempo nem perspectiva.', 'jovens', 'trabalho digno', 'reconhecimento do trabalho', 'achado', 'indício', NULL, '19'), ('D04-TR-068-tra', 'O repertório digital jovem traduz crítica social por humor, trend e experiência concreta, mais do que por explicação institucional longa.', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'achado', 'indício', NULL, '19'), ('D04-TR-069', 'Na escuta digital, o trabalho aparece como caminho de dignidade, reconhecimento e independência, mas também como fonte de exaustão e falta de equilíbrio.', 'jovens', 'trabalho digno', 'reconhecimento do trabalho', 'achado', 'indício', NULL, '19'), ('D04-TR-070', 'Entre jovens, ganham força na escuta digital temas como escala 6x1, shopping, primeiro emprego, desgaste, saúde mental e dificuldade de conciliar trabalho com vida.', 'jovens', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '19'), ('D04-TR-071', 'Há disputa narrativa sobre a proteção ao trabalhador: de um lado, proteção como valorização; de outro, acusação de populismo, impacto econômico ou acomodação da CLT.', 'jovens', 'trabalho digno', 'direitos trabalhistas', 'achado', 'indício', NULL, '19'), ('D04-TR-075', 'A macronarrativa Proteção ao Trabalhador organiza a tensão entre trabalho como dignidade e trabalho que toma a vida inteira.', 'jovens', 'trabalho digno', 'reconhecimento do trabalho', 'achado', 'indício', NULL, '20'), ('D04-TR-076', '"Trabalho como autonomia e reconhecimento" é isotopia reiterada: trabalhar é visto como caminho para independência, dignidade e valor social.', 'jovens', 'trabalho digno', 'reconhecimento do trabalho', 'achado', 'forte', NULL, '20'), ('D04-TR-077', '"Esforço sem recompensa suficiente" é isotopia reiterada: o esforço é aceito, mas gera frustração quando não vem acompanhado de remuneração, respeito, estabilidade ou possibilidade de crescer.', 'jovens', 'trabalho digno', 'reconhecimento do trabalho', 'achado', 'forte', NULL, '20'), ('D04-TR-078', '"Tempo capturado pelo trabalho" é isotopia reiterada: vida, tempo, escala e dias estruturam a sensação de que o trabalho ocupa o centro da existência.', 'jovens', 'trabalho digno', 'jornada de trabalho', 'achado', 'forte', NULL, '20'), ('D04-TR-079', '"Proteção sob disputa" é isotopia reiterada: os direitos trabalhistas aparecem entre valorização e desconfiança, atravessados por polarização, medo econômico e oposição entre CLT e empreendedorismo.', 'jovens', 'trabalho digno', 'direitos trabalhistas', 'achado', 'forte', NULL, '20'), ('D04-TR-080', 'O jovem quer trabalhar, ganhar o próprio dinheiro, sair da dependência, ajudar em casa e ser reconhecido pelo esforço.', 'jovens', 'trabalho digno', 'reconhecimento do trabalho', 'achado', 'indício', NULL, '20'), ('D04-TR-081', 'A crítica não é ao trabalho em si, mas ao modelo em que trabalhar muito não garante vida melhor, descanso, perspectiva ou qualidade de vida.', 'jovens', 'trabalho digno', 'reconhecimento do trabalho', 'achado', 'indício', NULL, '20'), ('D04-TR-082', 'O debate sobre proteção ganha força quando fala de jornada, escala 6x1, descanso, saúde mental, família, relacionamento e tempo de qualidade.', 'jovens', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '20'), ('D04-TR-088', 'O ponto não é opor "viver a juventude" ao trabalho: esses jovens querem trabalhar, mas não querem que o trabalho consuma toda a vida antes que consigam construir estabilidade, autonomia e futuro.', 'jovens', 'trabalho digno', 'reconhecimento do trabalho', 'achado', 'indício', NULL, '21'), ('D04-TR-090', 'A transformação em jogo não é "subir na vida" no sentido meritocrático: é sair de um estado em que o trabalho captura tudo para um estado em que o jovem começa a poder fazer, escolher e gerenciar a própria vida.', 'jovens', 'trabalho digno', 'reconhecimento do trabalho', 'achado', 'indício', NULL, '22'), ('D04-TR-091', 'O jovem trabalha, mas sua reivindicação por descanso, jornada justa e saúde mental é deslegitimada.', 'jovens', 'trabalho digno', 'etarismo', 'achado', 'indício', NULL, '22'), ('D04-TR-092', 'O estigma geracional aparece em formulações como "essa geração não quer trabalhar", "é acomodada", "não aguenta pressão" e "não valoriza oportunidade".', 'jovens', 'trabalho digno', 'etarismo', 'achado', 'indício', NULL, '22'), ('D04-TR-094', 'No estado de conjunção, o jovem é reconhecido como sujeito trabalhador: quer renda, autonomia e futuro, mas também tempo, descanso, saúde e dignidade.', 'jovens', 'trabalho digno', 'reconhecimento do trabalho', 'achado', 'indício', NULL, '22'), ('D04-TR-097', 'O ponto de tensão é o estigma de que a geração jovem "não quer trabalhar" quando reivindica descanso, jornada justa ou saúde mental.', 'jovens', 'trabalho digno', 'etarismo', 'achado', 'indício', NULL, '23'), ('D04-TR-099', 'Escala, tempo, deslocamento, domingo trabalhado, shopping, sono e cansaço materializam a sensação de que o trabalho ocupa tudo.', 'jovens', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '23'), ('D04-TR-100', 'Para os jovens, a captura da vida pelo trabalho afeta estudo, família, relacionamento, saúde mental e planos em formação.', 'jovens', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '23'), ('D04-TR-105', 'O debate sobre proteção aparece atravessado por disputa política: governo como proteção ou populismo, CLT como segurança ou acomodação, empreendedorismo como liberdade ou risco.', 'jovens', 'trabalho digno', 'direitos trabalhistas', 'achado', 'indício', NULL, '23'), ('D04-TR-108', 'O problema não é o esforço, mas a ideia de que sofrer, se exaurir e não ter tempo seriam provas de valor.', 'jovens', 'trabalho digno', 'reconhecimento do trabalho', 'achado', 'indício', NULL, '24'), ('D04-TR-109', 'Na narrativa da dignidade, o jovem é sujeito trabalhador em busca de legitimidade: quer renda, autonomia, reconhecimento e futuro, mas também descanso, saúde mental, jornada justa e respeito.', 'jovens', 'trabalho digno', 'reconhecimento do trabalho', 'achado', 'indício', NULL, '24'), ('D04-TR-111', 'Transformação narrativa em jogo: no estado inicial, o jovem é atravessado pelo estigma geracional e sua demanda por descanso, jornada ou saúde mental pode ser lida como falta de vontade de trabalhar; a comunicação reenquadra a demanda, apresentando a proteção como condição para que o trabalho siga sendo fonte de autonomia, renda e reconhecimento; no estado final, o jovem é reconhecido como trabalhador legítimo, que se esforça mas não aceita que a dignidade dependa de exaustão, ausência de descanso ou vida sempre no limite.', 'jovens', 'trabalho digno', 'etarismo', 'achado', 'indício', NULL, '24'), ('D04-TR-113', 'Na narrativa do trabalho que cabe na vida, o jovem é sujeito que tenta equilibrar responsabilidades: trabalha, estuda, se desloca, ajuda em casa, cuida de vínculos e tenta construir futuro sem ser consumido pela rotina.', 'jovens', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '25'), ('D04-TR-115', 'Transformação narrativa em jogo: no estado inicial, o trabalho ocupa o centro da vida e a rotina gira em torno de escala, deslocamento, cansaço e pouco tempo para estudo, família, namoro, descanso ou saúde mental; a comunicação mostra que jornada, descanso, direito e previsibilidade não são detalhes, mas condições para que o trabalho deixe de capturar tudo; no estado final, o jovem continua trabalhando com mais margem para viver: descansar, estudar, cuidar, circular, conviver e planejar sem que a vida inteira seja organizada pelo cansaço.', 'jovens', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '25'), ('D04-TR-117', 'Na narrativa do direito explicado, o jovem é sujeito em formação de trajetória: aprende as regras do trabalho enquanto trabalha, negocia oportunidades, tenta ganhar autonomia e muitas vezes não sabe exatamente que direito tem ou onde buscar apoio.', 'jovens', 'trabalho digno', 'direitos trabalhistas', 'achado', 'indício', NULL, '26'), ('D04-TR-119', 'Transformação narrativa em jogo: no estado inicial, o jovem entra no mercado com pouca experiência, informação fragmentada e medo de perder oportunidade se questionar escala, salário, descanso, benefício ou condição de trabalho; a comunicação transforma o direito em ferramenta de segurança, explicando jornada, descanso, salário, benefício, licença, formalização, fiscalização e canais de apoio em linguagem simples; no estado final, o jovem ganha repertório para reconhecer abuso, buscar proteção, decidir melhor e construir trajetória com mais previsibilidade, sem depender só do improviso ou da sorte.', 'jovens', 'trabalho digno', 'direitos trabalhistas', 'achado', 'indício', NULL, '26'), ('D04-TR-121', 'Na narrativa da proteção sem polarização, o jovem é sujeito que avalia a política pela consequência prática: quer saber se a medida melhora salário, descanso, estabilidade, saúde mental, oportunidade e condições reais de trabalho.', 'jovens', 'trabalho digno', 'direitos trabalhistas', 'achado', 'indício', NULL, '27'), ('D04-TR-123', 'Transformação narrativa em jogo: no estado inicial, a proteção aparece capturada por disputas ideológicas, entre acusação de populismo, medo de impacto econômico, crítica à CLT e oposição entre trabalhador e empreendedor; a comunicação desloca o foco da briga política para a vida real, com jornada, renda, descanso, segurança, reconhecimento e possibilidade de seguir trabalhando com dignidade; no estado final, o jovem reconhece a proteção como pauta legítima de quem trabalha, independentemente de formato ou vínculo: CLT, bico, MEI, aplicativo, loja, shopping ou informalidade.', 'jovens', 'trabalho digno', 'direitos trabalhistas', 'achado', 'indício', NULL, '27'), ('D04-TR-192', 'Os jovens desse perfil não são adolescentes desobrigados nem adultos plenamente estabilizados: trabalham, estudam, ajudam em casa, formam família e projetam futuro sob pressão.', 'jovens', 'trabalho digno', 'condição juvenil', 'achado', 'indício', NULL, '39'), ('D04-TR-197-tra', 'A força das macronarrativas está em transformar pressão cotidiana em informação, proteção e horizonte possível.', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'achado', 'indício', NULL, '40'), ('D06-TR-025', 'Trabalho, estudo, deslocamento e casa ocupam a maior parte da rotina.', 'jovens', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '11'), ('D06-TR-026', 'O tempo livre aparece menos como lazer e mais como recuperação física e mental.', 'jovens', 'trabalho digno', 'jornada de trabalho', 'achado', 'indício', NULL, '11'), ('D06-TR-079', 'Proteção do trabalhador é o território mais transversal: salário, escala 6x1, primeiro emprego, experiência, descanso, direitos e saúde mental. Potencial narrativo muito alto, porque organiza cansaço, dignidade e futuro; precisa falar de tempo de vida, não só de legislação.', 'jovens', 'trabalho digno', 'jornada de trabalho', 'achado', 'forte', NULL, '32'), ('D06-TR-092', 'Proteger quem trabalha é devolver tempo, dignidade e futuro.', 'jovens', 'trabalho digno', 'jornada de trabalho', 'achado', 'forte', NULL, '34'), ('D06-TR-093', 'O território do trabalho é o mais forte: Ele organiza quase todos os outros temas ( dinheiro, cansaço, família, estudo, saúde mental, futuro e voto). ', 'jovens', 'trabalho digno', 'jornada de trabalho', 'achado', 'forte', NULL, '34'), ('D06-TR-096', 'Entre homens, o tema aparece conectado à provisão e à responsabilidade. Entre mulheres, soma-se à luta por credibilidade, ao cansaço e à desigualdade no ambiente de trabalho.', 'jovens', 'trabalho digno', 'reconhecimento do trabalho', 'achado', 'indício', NULL, '34'), ('D06-TR-141-tra', 'Explicar quem decide transforma desconfiança em possibilidade de cobrança.', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'achado', 'indício', NULL, '40'), ('D06-TR-143-tra', 'Há uma lacuna clara: muitos sabem que política importa, mas não necessariamente sabem onde cada decisão acontece.', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'achado', 'indício', NULL, '40'), ('D04-TR-209', 'Reproduzir o estigma de que "essa geração não quer trabalhar", "é acomodada" ou "não aguenta pressão" afasta e deslegitima a demanda por descanso, jornada justa e saúde mental.', 'jovens', 'trabalho digno', 'etarismo', 'afasta', NULL, NULL, '22'), ('D04-TR-210', 'Apresentar proteção ao trabalhador como privilégio, acomodação ou ação populista afasta: proteção precisa aparecer como condição para trabalhar melhor.', 'jovens', 'trabalho digno', 'direitos trabalhistas', 'afasta', NULL, NULL, '19'), ('D04-TR-211', 'Enquadrar a proteção ao trabalhador como disputa política, "governo x populismo" ou "CLT x empreendedorismo", afasta: o tema precisa voltar à experiência concreta de quem trabalha.', 'jovens', 'trabalho digno', 'direitos trabalhistas', 'afasta', NULL, NULL, '27'), ('D04-TR-212', 'Apresentar direitos em linguagem jurídica distante afasta: direito precisa virar orientação prática, o que é, para quem vale, como acessar, onde checar.', 'jovens', 'trabalho digno', 'informação sobre direitos', 'afasta', NULL, NULL, '23'), ('D04-TR-213', 'Romantizar o sofrimento ou tratar exaustão e falta de tempo como prova de valor afasta: o esforço deve ser validado sem exigir sacrifício.', 'jovens', 'trabalho digno', 'reconhecimento do trabalho', 'afasta', NULL, NULL, '24'), ('D04-TR-214', 'Opor juventude a trabalho, como se esses jovens quisessem "viver a juventude" em vez de trabalhar, afasta: eles querem trabalhar sem que o trabalho consuma toda a vida.', 'jovens', 'trabalho digno', 'juventude e trabalho', 'afasta', NULL, NULL, '21'), ('D04-TR-215', 'Explicação institucional longa afasta: a crítica social deste público circula por humor, trend e experiência concreta.', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'afasta', NULL, NULL, '19'), ('D04-TR-216', 'Slogan afasta: mensagens sobre proteção precisam mostrar quem ganha, como funciona, que problema resolve e por que importa para quem trabalha hoje.', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'afasta', NULL, NULL, '27'), ('D04-TR-228-tra', 'Infantilizar afasta: esses jovens podem ter trabalho, família e filhos, e precisam ser reconhecidos como jovens sem serem tratados como adolescentes.', 'jovens', 'trabalho digno', 'condição juvenil', 'afasta', NULL, NULL, '40'), ('D04-TR-229-tra', 'Cobrar que o jovem resolva sozinho o que é estrutural afasta: ele precisa de informação simples, proteção efetiva e caminhos claros.', 'jovens', 'trabalho digno', 'autonomia e amparo', 'afasta', NULL, NULL, '40'), ('D04-TR-230-tra', 'Convocação abstrata afasta: a comunicação precisa começar nos temas que já organizam a rotina, estudo, transporte, consumo, primeiro emprego, escala, família e segurança.', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'afasta', NULL, NULL, '40'), ('D06-TR-064', 'Comunicação sobre juventude, trabalho perde força quando trata homens e mulheres como se enfrentassem a mesma carga.', 'jovens', 'trabalho digno', 'gênero e trabalho', 'afasta', NULL, NULL, '14'), ('D06-TR-162-tra', 'Falar com um "jovem" abstrato afasta: este público se mede por responsabilidade, tempo curto, dinheiro, família e futuro, e precisa ser tratado como jovem adulto.', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'afasta', NULL, NULL, '10'), ('D06-TR-163-tra', 'Reproduzir estereótipos de jovem irresponsável, geração que não quer trabalhar ou gente sem experiência para opinar afasta: a juventude vira marca de suspeita e gera irritação.', 'jovens', 'trabalho digno', 'etarismo', 'afasta', NULL, NULL, '11'), ('D06-TR-165-tra', 'Mensagens sobre futuro que soam apenas inspiracionais afastam: futuro crível mostra caminho, condição e proteção.', 'jovens', 'trabalho digno', 'futuro possível', 'afasta', NULL, NULL, '13'), ('D06-TR-167-tra', 'Reduzir a comunicação com jovens a "linguagem jovem" afasta: o que aproxima é reconhecer uma juventude encurtada por trabalho, família, medo e necessidade de construir futuro cedo.', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'afasta', NULL, NULL, '15'), ('D04-TR-102', 'Muitos jovens estão entrando ou se firmando no mercado de trabalho: primeiro emprego, CLT, bico, MEI, aplicativo, loja, shopping e informalidade.', 'jovens', 'trabalho digno', 'juventude e trabalho', 'contexto', NULL, NULL, '23'), ('D06-TR-095', 'Não se trata apenas de direito trabalhista: trata-se de ter vida fora do trabalho, poder descansar, estudar, cuidar da família e não adoecer.', 'jovens', 'trabalho digno', 'jornada de trabalho', 'contexto', NULL, NULL, '34'), ('D01-TR-119', 'Mostrar que proteger o trabalhador é devolver uma vida digna: descansar, estudar, cuidar, circular, conviver e planejar sem que o trabalho engula todas as outras dimensões.', 'jovens', 'trabalho digno', 'jornada de trabalho', 'funciona', NULL, NULL, '45'), ('D01-TR-120', 'Transformar direito em ferramenta prática: entender jornada, descanso, salário, benefício, licença, segurança, formalização e canais de apoio para não ficar sozinho diante do sistema.', 'jovens', 'trabalho digno', 'direitos trabalhistas', 'funciona', NULL, NULL, '45'), ('D01-TR-121', 'A escala 6x1 funciona como atalho narrativo porque traduz uma discussão institucional em experiência vivida.', 'jovens', 'trabalho digno', 'jornada de trabalho', 'funciona', NULL, NULL, '45'), ('D04-TR-009', 'A proteção deve aparecer como condição para trabalhar melhor, não como privilégio: direitos, jornada, descanso e segurança ajudam o trabalho a não consumir toda a vida.', 'jovens', 'trabalho digno', 'direitos trabalhistas', 'funciona', NULL, NULL, '8'), ('D04-TR-018-tra', 'O conteúdo aproxima mais quando vem em formato curto e real: relato, bastidor, tutorial, comparação, antes e depois e dica prática.', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'funciona', NULL, NULL, '10'), ('D04-TR-048-tra', 'Relatos, tutoriais, bastidores, antes e depois e linguagem direta aproximam mais do que propaganda.', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'funciona', NULL, NULL, '14'), ('D04-TR-067', 'Conteúdos com cara de vida real funcionam melhor no tema do trabalho: bastidor de rotina, relato pessoal, humor de identificação, comparação entre escalas e "pov" do trabalhador jovem.', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'funciona', NULL, NULL, '19'), ('D04-TR-072', 'A narrativa precisa reconhecer que esses jovens querem trabalhar, mas não querem que o trabalho bloqueie estudo, saúde, família, descanso e construção de futuro.', 'jovens', 'trabalho digno', 'reconhecimento do trabalho', 'funciona', NULL, NULL, '19'), ('D04-TR-073', 'Proteção ao Trabalhador deve mostrar que direito não é privilégio: é condição para trabalhar com dignidade, descanso e previsibilidade.', 'jovens', 'trabalho digno', 'direitos trabalhistas', 'funciona', NULL, NULL, '19'), ('D04-TR-074', 'A comunicação precisa sair da polarização e mostrar proteção como algo prático: jornada, descanso, renda, segurança, saúde mental e tempo de qualidade.', 'jovens', 'trabalho digno', 'direitos trabalhistas', 'funciona', NULL, NULL, '19'), ('D04-TR-083', 'A comunicação precisa mostrar proteção como condição para trabalhar melhor, não como privilégio, acomodação ou ação populista.', 'jovens', 'trabalho digno', 'direitos trabalhistas', 'funciona', NULL, NULL, '20'), ('D04-TR-084', 'Figuras que materializam o valor do trabalho: primeiro emprego, carteira assinada, vale-alimentação, salário, uniforme, loja, trabalho no shopping, contrato e "mão suja, dinheiro limpo".', 'jovens', 'trabalho digno', 'juventude e trabalho', 'funciona', NULL, NULL, '20'), ('D04-TR-085', 'Figuras do esforço sem recompensa: salário curto, hora extra, bico, múltiplas fontes de renda, promoção distante, comparação com outros países e "Brasil não valoriza trabalhador".', 'jovens', 'trabalho digno', 'renda e sustento', 'funciona', NULL, NULL, '20'), ('D04-TR-086', 'Figuras do tempo capturado: escala 6x1, domingo trabalhado, uma folga, trabalho no shopping, transporte, sono, cansaço, burnout, namoro difícil e "trabalhamos demais".', 'jovens', 'trabalho digno', 'jornada de trabalho', 'funciona', NULL, NULL, '20'), ('D04-TR-087', 'Figuras da proteção em disputa: CLT, MEI, aplicativo, benefício, direito, Estado, governo, imposto, populismo, "não quer trabalhar" e "trabalhar com dignidade".', 'jovens', 'trabalho digno', 'direitos trabalhistas', 'funciona', NULL, NULL, '20'), ('D04-TR-089', 'A macronarrativa precisa deslocar o jovem do lugar de suspeita para o lugar de sujeito legítimo da reivindicação.', 'jovens', 'trabalho digno', 'etarismo', 'funciona', NULL, NULL, '22'), ('D04-TR-093', 'A narrativa desloca a leitura da recusa do trabalho para a recusa da exaustão sem recompensa; a proteção aparece como condição para trabalhar melhor.', 'jovens', 'trabalho digno', 'etarismo', 'funciona', NULL, NULL, '22'), ('D04-TR-095', 'O deslocamento narrativo acontece quando a proteção desfaz o estigma e legitima a demanda por melhores condições de trabalho.', 'jovens', 'trabalho digno', 'etarismo', 'funciona', NULL, NULL, '22'), ('D04-TR-096', 'Proteção ao Trabalhador precisa mostrar que o jovem quer trabalhar, mas não quer perder a vida para o trabalho.', 'jovens', 'trabalho digno', 'reconhecimento do trabalho', 'funciona', NULL, NULL, '23'), ('D04-TR-098', 'Reenquadrar a demanda jovem: proteção não é privilégio nem preguiça, é condição para trabalhar melhor, continuar produzindo e construir futuro com dignidade.', 'jovens', 'trabalho digno', 'direitos trabalhistas', 'funciona', NULL, NULL, '23'), ('D04-TR-101', 'Mostrar que proteger o trabalhador é devolver margem de vida: descansar, estudar, cuidar, circular, conviver e planejar sem que o trabalho engula todas as outras dimensões.', 'jovens', 'trabalho digno', 'jornada de trabalho', 'funciona', NULL, NULL, '23'), ('D04-TR-103', 'A proteção precisa ser traduzida para situações concretas, não como linguagem jurídica distante.', 'jovens', 'trabalho digno', 'direitos trabalhistas', 'funciona', NULL, NULL, '23'), ('D04-TR-106', 'Tirar a proteção do enquadramento ideológico e recolocá-la no cotidiano: quem trabalha precisa de reconhecimento, estabilidade, descanso, renda e condições para seguir.', 'jovens', 'trabalho digno', 'direitos trabalhistas', 'funciona', NULL, NULL, '23'), ('D04-TR-107', 'A narrativa precisa deslocar o jovem do estigma de "não quer trabalhar" para o reconhecimento de que ele quer trabalhar com dignidade.', 'jovens', 'trabalho digno', 'etarismo', 'funciona', NULL, NULL, '24'), ('D04-TR-110', 'Validar o esforço sem romantizar o sofrimento: mostrar jovens que trabalham, estudam, ajudam em casa ou sustentam família e reivindicam condições para continuar, sem serem reduzidos à preguiça ou à acomodação.', 'jovens', 'trabalho digno', 'etarismo', 'funciona', NULL, NULL, '24'), ('D04-TR-112', 'A proteção precisa mostrar que trabalho digno não é apenas ter renda: é ter tempo, descanso e saúde para que estudo, família, relacionamento e planos também caibam na vida.', 'jovens', 'trabalho digno', 'jornada de trabalho', 'funciona', NULL, NULL, '25'), ('D04-TR-114', 'Partir de cenas reconhecíveis: escala 6x1, shopping, domingo trabalhado, transporte, sono atrasado, cansaço, uma folga na semana e dificuldade de estudar, conviver ou descansar.', 'jovens', 'trabalho digno', 'jornada de trabalho', 'funciona', NULL, NULL, '25'), ('D04-TR-116', 'A proteção precisa sair da linguagem abstrata dos direitos e entrar nas situações concretas de quem está começando ou tentando se firmar no trabalho: primeiro emprego, loja, shopping, CLT, bico, MEI, aplicativo e informalidade.', 'jovens', 'trabalho digno', 'direitos trabalhistas', 'funciona', NULL, NULL, '26'), ('D04-TR-118', 'Traduzir direito em orientação prática: o que é, para quem vale, como acessar, onde checar, o que fazer quando não é cumprido e que diferença isso faz na rotina.', 'jovens', 'trabalho digno', 'direitos trabalhistas', 'funciona', NULL, NULL, '26'), ('D04-TR-120', 'A proteção ao trabalhador precisa escapar de disputas do tipo governo versus populismo ou CLT versus empreendedorismo e voltar para a experiência concreta de quem trabalha; o tema deve ser apresentado como pauta de dignidade, não como torcida política.', 'jovens', 'trabalho digno', 'direitos trabalhistas', 'funciona', NULL, NULL, '27'), ('D04-TR-122', 'Usar linguagem despolarizada e verificável: menos slogan, mais efeito concreto, mostrando quem ganha, como funciona, que problema resolve e por que isso importa para quem trabalha hoje.', 'jovens', 'trabalho digno', 'direitos trabalhistas', 'funciona', NULL, NULL, '27'), ('D04-TR-190-tra', 'Comunicar com concretude, linguagem simples, prova verificável e formatos próximos: relato, bastidor, tutorial, antes e depois, humor e checagem.', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'funciona', NULL, NULL, '39'), ('D04-TR-198', 'Reconhecer a juventude sem infantilizar: esses jovens podem já ter trabalho, família, filhos ou responsabilidades adultas, mas ainda estão formando trajetória, repertório político, autonomia financeira e projeto de futuro.', 'jovens', 'trabalho digno', 'condição juvenil', 'funciona', NULL, NULL, '40'), ('D04-TR-199-tra', 'Transformar políticas em condição de vida melhor: dinheiro, trabalho e engajamento precisam aparecer como suporte concreto, como pagar o básico, sair da dívida, trabalhar com dignidade, entender direitos, checar informações e cobrar resultados.', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D04-TR-200-tra', 'Partir da vida real, não da convocação abstrata: a comunicação deve começar nos temas que já organizam a rotina, como estudo, transporte, consumo, primeiro emprego, escala, Pix, taxa das blusinhas, família, segurança, voto e futuro.', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D04-TR-201-tra', 'Dar competência sem transferir responsabilidade: o jovem não precisa ser cobrado a resolver sozinho o que é estrutural, e sim de informação simples, proteção efetiva e caminhos claros para viver melhor, decidir com mais segurança e voltar a vislumbrar futuro.', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D06-TR-003-tra', 'As narrativas de maior força são as que partem da vida concreta.', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'funciona', NULL, NULL, '7'), ('D06-TR-006', 'Trabalho mobiliza quando a mensagem trata de salário, descanso, escala, cansaço e possibilidade de viver fora do expediente.', 'jovens', 'trabalho digno', 'jornada de trabalho', 'funciona', NULL, NULL, '7'), ('D06-TR-142-tra', 'Responsabilização é menos um território emocional e mais uma chave de tradução: ganha força quando explica por que o voto para Legislativo, Senado e Congresso afeta salário, escala, direitos, internet, transporte, segurança e programas.', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D06-TR-144-tra', 'Quando a comunicação traduz quem aprova, quem bloqueia, quem executa e quem responde, a política deixa de parecer um bloco distante.', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D06-TR-155-tra', 'Proteção do trabalhador, dinheiro no bolso e proteção da família são os territórios de maior lastro espontâneo — já estão na vida dos jovens antes da política aparecer, por isso devem funcionar como portas de entrada principais.', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'funciona', NULL, NULL, '42'), ('D06-TR-156-tra', 'Brasil Core e Engajamento Cívico têm potencial, mas precisam de prova: Brasil precisa aparecer como cultura vivida e soberania concreta; Engajamento precisa mostrar onde a voz jovem produz efeito.', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'funciona', NULL, NULL, '42'), ('D06-TR-158-tra', 'Responsabilização e Senado é a principal ponte pedagógica: não mobiliza sozinho, mas ajuda a transformar temas concretos em escolha eleitoral, mostrando quem aprova, quem trava, quem amplia e quem ameaça.', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'funciona', NULL, NULL, '42'), ('D06-TR-035', '“É basicamente uma rotina dupla de trabalho, mas estudo à noite. Então é bem cansativo.”', 'jovens', 'trabalho digno', 'jornada de trabalho', 'verbatim', NULL, NULL, '11'), ('D06-TR-036', '“As pessoas têm a ideia de que ser jovem é ser irresponsável. Isso me incomoda, porque eu sou altamente responsável com tudo.”', 'jovens', 'trabalho digno', 'etarismo', 'verbatim', NULL, NULL, '11'), ('D06-TR-066', '“Por ser mulher e por ser jovem, eu preciso lutar muito mais e construir muito mais conhecimento para poder me provar.”', 'jovens', 'trabalho digno', 'reconhecimento do trabalho', 'verbatim', NULL, NULL, '14'), ('D06-TR-097', '“Eu comecei a trabalhar com dezesseis ainda como jovem aprendiz. Então já tenho dez anos no mercado de trabalho.”', 'jovens', 'trabalho digno', 'juventude e trabalho', 'verbatim', NULL, NULL, '34'), ('D06-TR-098', '“A gente só está ali lutando por condições melhores de trabalho.”', 'jovens', 'trabalho digno', 'jornada de trabalho', 'verbatim', NULL, NULL, '34'), ('D06-TR-146-tra', '“São eles que discutem a pauta. São eles que aprovam e desaprovam. Então a nossa vida passa na mão dos deputados.”', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'verbatim', NULL, NULL, '40'), ('D06-TR-147', '“A escala 6x1 passa na mão do deputado. A nossa condição social passa na mão de deputados. O aumento do salário mínimo passou pela mão de deputados.”', 'jovens', 'trabalho digno', 'jornada de trabalho', 'verbatim', NULL, NULL, '40'), ('D06-TR-148-tra', '“As pessoas votam para senador, para deputado, mas não sabem o que fazem. Acham que o importante é só o presidente e o governador.”', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'verbatim', NULL, NULL, '40'), ('D06-TR-149-tra', '“Seria interessante se ensinassem na escola a atribuição de cada um.”', 'jovens', 'trabalho digno', 'comunicação e linguagem', 'verbatim', NULL, NULL, '40'), ('D01-TR-028-jov', 'As políticas públicas fazem parte do dia a dia sem serem necessariamente lembradas de forma espontânea; a percepção dos benefícios é muitas vezes escassa ou pouco associada a um governo ou período específico.', 'jovens', 'família e cuidado', 'atribuição de políticas públicas', 'achado', 'indício', NULL, '17'), ('D01-TR-041-jov', 'A falta de rede de apoio é apontada como marca comum dos perfis de mulheres.', 'jovens', 'família e cuidado', 'rede de apoio', 'achado', 'indício', NULL, '18'), ('D01-TR-053-jov', 'Segurança pública é problema concreto na vida da mulher.', 'jovens', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '23'), ('D01-TR-055-jov', 'A família e cuidado é entendida como conjunto multifacetado: segurança física (ruas, escola, creche), segurança digital (crianças e redes sociais), acesso a saúde e educação, e estabilidade financeira.', 'jovens', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '24'), ('D01-TR-056-jov', 'Entre os participantes deste estudo, o medo da violência é universal, visceral e transversal, mas nenhuma resposta institucional convence.', 'jovens', 'família e cuidado', 'segurança pública', 'achado', 'forte', NULL, '25'), ('D01-TR-058-jov', 'Medida protetiva e Delegacia da Mulher são termos conhecidos, mas a desconfiança na eficácia real permanece.', 'jovens', 'família e cuidado', 'violência contra a mulher', 'achado', 'indício', NULL, '25'), ('D01-TR-122', 'Família aproxima quando deixa de ser valor abstrato e vira proteção de quem está perto; é território mobilizador, mas ambivalente.', 'jovens', 'família e cuidado', 'família e maternidade', 'achado', 'indício', NULL, '46'), ('D01-TR-123', 'A família aparece como apoio, cobrança, responsabilidade, segurança, cuidado, futuro dos filhos e papel de provedor.', 'jovens', 'família e cuidado', 'família e maternidade', 'achado', 'indício', NULL, '46'), ('D01-TR-125', 'Para homens jovens, a família e cuidado passa por prover, proteger e manter controle sobre o "porta para dentro".', 'jovens', 'família e cuidado', 'família e maternidade', 'achado', 'indício', NULL, '47'), ('D01-TR-126', 'Para mulheres jovens, a família e cuidado passa por cuidado e segurança.', 'jovens', 'família e cuidado', 'família e maternidade', 'achado', 'indício', NULL, '47'), ('D01-TR-127', 'A segurança define até onde a vida pode circular: não é um medo abstrato, é uma limitação concreta.', 'jovens', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '48'), ('D01-TR-128', 'Para mulheres jovens, a insegurança é experiência direta: assédio, violência sexual, medo de voltar tarde, necessidade de gastar com transporte por aplicativo ou pedir para alguém buscar.', 'jovens', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '48'), ('D01-TR-129', 'Para homens jovens, a insegurança aparece deslocada: preocupação com a mãe, irmã, esposa ou filha.', 'jovens', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '48'), ('D03-TR-007-jov', 'Família é a opção mais citada como mais importante na vida hoje: 57,2% em primeira opção e 80,3% somando primeira e segunda opções.', 'jovens', 'família e cuidado', 'família e maternidade', 'achado', 'indício', NULL, '16'), ('D03-TR-008-jov', 'Saúde e bem-estar é a segunda opção mais citada como mais importante na vida hoje: 22,5% em primeira opção e 55,9% somando primeira e segunda opções.', 'jovens', 'família e cuidado', 'saúde e sus', 'achado', 'indício', NULL, '16'), ('D03-TR-009-jov', 'Fé e religiosidade aparece como terceira opção mais importante na vida hoje: 11,2% em primeira opção e 30,4% somando primeira e segunda opções.', 'jovens', 'família e cuidado', 'fé e religiosidade', 'achado', 'indício', NULL, '16'), ('D03-TR-011-jov', 'Tempo livre e viagens é citado por 1,4% como opção mais importante na vida hoje e por 5,7% somando primeira e segunda opções.', 'jovens', 'família e cuidado', 'cultura e lazer', 'achado', 'indício', NULL, '16'), ('D03-TR-012-jov', 'Esporte, cultura e lazer é citado por 1,3% como opção mais importante na vida hoje e por 4,6% somando primeira e segunda opções.', 'jovens', 'família e cuidado', 'cultura e lazer', 'achado', 'indício', NULL, '16'), ('D03-TR-069-jov', 'A educação pública na gestão federal recebe 27,7% de avaliação ótima ou boa e 33,0% ruim ou péssima.', 'jovens', 'família e cuidado', 'educação', 'achado', 'indício', NULL, '73'), ('D03-TR-072-jov', 'A saúde pública na gestão federal recebe 21,5% de avaliação ótima ou boa e 44,5% ruim ou péssima, com apenas 1,4% sem saber avaliar.', 'jovens', 'família e cuidado', 'saúde e sus', 'achado', 'indício', NULL, '73'), ('D03-TR-073-jov', 'A segurança pública na gestão federal recebe 21,3% de avaliação ótima ou boa e 40,2% ruim ou péssima.', 'jovens', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '73'), ('D03-TR-076-jov', 'O Minha Casa, Minha Vida Classe Média é o programa federal mais conhecido (82,8%) e o de melhor avaliação da lista: 70,1% ótima ou boa e 9,0% ruim ou péssima.', 'jovens', 'família e cuidado', 'moradia e cidade', 'achado', 'indício', NULL, '76'), ('D03-TR-077-jov', 'O Pé-de-Meia, com 200 reais por aluno, é conhecido por 81,0%; a avaliação é 64,4% ótima ou boa e 17,5% ruim ou péssima.', 'jovens', 'família e cuidado', 'educação', 'achado', 'indício', NULL, '76'), ('D04-TR-068-fam', 'O repertório digital jovem traduz crítica social por humor, trend e experiência concreta, mais do que por explicação institucional longa.', 'jovens', 'família e cuidado', 'comunicação e linguagem', 'achado', 'indício', NULL, '19'), ('D04-TR-197-fam', 'A força das macronarrativas está em transformar pressão cotidiana em informação, proteção e horizonte possível.', 'jovens', 'família e cuidado', 'comunicação e linguagem', 'achado', 'indício', NULL, '40'), ('D06-TR-011', 'Família não aparece como valor abstrato, e sim como mãe, filho, irmã, esposa, casa, escola, cuidado e volta em paz.', 'jovens', 'família e cuidado', 'família e maternidade', 'achado', 'indício', NULL, '7'), ('D06-TR-012', 'Segurança importa porque define se é possível trabalhar, estudar, sair, voltar e proteger quem está perto.', 'jovens', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '7'), ('D06-TR-037', 'Família aparece como afeto, energia e referência e também como responsabilidade concreta.', 'jovens', 'família e cuidado', 'família e maternidade', 'achado', 'indício', NULL, '12'), ('D06-TR-038', 'Ter filho, cuidar da mãe, ajudar em casa ou ser provedor muda a régua de futuro.', 'jovens', 'família e cuidado', 'família e maternidade', 'achado', 'indício', NULL, '12'), ('D06-TR-039', 'Entre mulheres com filhos, a família desloca o futuro para a logística do cuidado: estudar, estagiar ou trabalhar depende de quem fica com a criança, quanto custa a escola, como muda a rotina e que tipo de adulto o filho vai se tornar.', 'jovens', 'família e cuidado', 'educação', 'achado', 'indício', NULL, '12'), ('D06-TR-041', 'Entre homens, a família aparece mais como apoio moral e expectativa de realização e também como responsabilidade de sustento.', 'jovens', 'família e cuidado', 'renda e sustento', 'achado', 'indício', NULL, '12'), ('D06-TR-060', 'Ser jovem e mulher no trabalho pode significar menos credibilidade e necessidade de demonstrar mais preparo para ser levada a sério.', 'jovens', 'família e cuidado', 'reconhecimento do trabalho', 'achado', 'indício', NULL, '14'), ('D06-TR-061', 'Na rua, no transporte e no trabalho, a segurança aparece como medo concreto: assédio, violência sexual, volta para casa, custo de Uber, horários e dependência de alguém buscar.', 'jovens', 'família e cuidado', 'violência contra a mulher', 'achado', 'indício', NULL, '14'), ('D06-TR-062', 'Proteção não é valor abstrato: é respeito, segurança, renda, tempo, cuidado e liberdade para circular sem medo.', 'jovens', 'família e cuidado', 'violência contra a mulher', 'achado', 'indício', NULL, '14'), ('D06-TR-063', 'A maternidade intensifica essa lógica: o futuro próprio passa a ser organizado junto com a proteção da criança, com trabalho, estágio, escola, renda e rede de apoio precisando funcionar ao mesmo tempo.', 'jovens', 'família e cuidado', 'gênero e trabalho', 'achado', 'indício', NULL, '14'), ('D06-TR-065', 'Proteção precisa significar respeito, segurança, autonomia, credibilidade e condição real de circular, trabalhar e cuidar sem medo.', 'jovens', 'família e cuidado', 'violência contra a mulher', 'achado', 'indício', NULL, '14'), ('D06-TR-073', 'Para homens, a juventude aparece mais associada à cobrança por sustento, direção e estabilidade.', 'jovens', 'família e cuidado', 'renda e sustento', 'achado', 'indício', NULL, '15'), ('D06-TR-080', 'Proteção da família: família é apoio, obrigação e destino da esperança — para mulheres conecta cuidado e segurança, para homens provisão e proteção. Potencial narrativo muito alto, desde que saia da moral abstrata e entre em segurança, escola, saúde, renda, internet, trabalho e volta para casa.', 'jovens', 'família e cuidado', 'família e maternidade', 'achado', 'indício', NULL, '32'), ('D06-TR-100', 'Família aproxima quando deixa de ser valor abstrato e vira proteção de quem está perto.', 'jovens', 'família e cuidado', 'família e maternidade', 'achado', 'indício', NULL, '35'), ('D06-TR-101', 'Família é um território altamente mobilizador, mas ambivalente: aparece como apoio, cobrança, responsabilidade, segurança, cuidado, futuro dos filhos e papel de provedor.', 'jovens', 'família e cuidado', 'família e maternidade', 'achado', 'indício', NULL, '35'), ('D06-TR-104', 'Para mulheres, proteção da família passa por cuidado e segurança. Para homens, passa por prover, proteger e manter controle sobre o "porta para dentro".', 'jovens', 'família e cuidado', 'família e maternidade', 'achado', 'indício', NULL, '35'), ('D06-TR-108', 'A proteção mais crível começa na cena da "volta para casa".', 'jovens', 'família e cuidado', 'violência contra a mulher', 'achado', 'indício', NULL, '36'), ('D06-TR-109', 'Segurança pública atravessa o território da família, sobretudo entre mulheres: não aparece apenas como criminalidade abstrata, mas como medo no deslocamento, assédio, violência sexual, trabalho que termina tarde, custo de Uber e necessidade de pedir ajuda.', 'jovens', 'família e cuidado', 'violência contra a mulher', 'achado', 'indício', NULL, '36'), ('D06-TR-110', 'Nos homens, a segurança frequentemente aparece deslocada para mulheres próximas (filhas, irmãs, mães)', 'jovens', 'família e cuidado', 'violência contra a mulher', 'achado', 'indício', NULL, '36'), ('D06-TR-141-fam', 'Explicar quem decide transforma desconfiança em possibilidade de cobrança.', 'jovens', 'família e cuidado', 'comunicação e linguagem', 'achado', 'indício', NULL, '40'), ('D06-TR-143-fam', 'Há uma lacuna clara: muitos sabem que política importa, mas não necessariamente sabem onde cada decisão acontece.', 'jovens', 'família e cuidado', 'comunicação e linguagem', 'achado', 'indício', NULL, '40'), ('D07-TR-003-jov', 'Educação pública figura entre as três áreas de maior peso na avaliação pública de desempenho governamental.', 'jovens', 'família e cuidado', 'educação', 'achado', 'indício', NULL, '3'), ('D07-TR-004-jov', 'Incentivo ao esporte, cultura e lazer tem peso muito baixo na formação da avaliação pública de desempenho governamental.', 'jovens', 'família e cuidado', 'cultura e lazer', 'achado', 'indício', NULL, '3'), ('D07-TR-006-jov', 'Segurança pública situa-se em faixa alta de peso na avaliação pública de desempenho governamental, em patamar próximo ao de educação.', 'jovens', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '3'), ('D07-TR-007-jov', 'Saúde pública, ainda que serviço de uso cotidiano, pesa menos na avaliação de desempenho governamental do que temas de percepção difusa como custo de vida e posição do país no exterior.', 'jovens', 'família e cuidado', 'saúde e sus', 'achado', 'indício', NULL, '3'), ('D07-TR-008-jov', 'Programas sociais de modo geral ocupam faixa intermediária de peso na avaliação pública de desempenho governamental.', 'jovens', 'família e cuidado', 'bolsa família e transferência de renda', 'achado', 'indício', NULL, '3'), ('D07-TR-009-jov', 'Programas de habitação e moradia ocupam faixa intermediária de peso na avaliação pública de desempenho governamental.', 'jovens', 'família e cuidado', 'moradia e cidade', 'achado', 'indício', NULL, '3'), ('D07-TR-010-jov', 'Combate às desigualdades e privilégios tem peso baixo na formação da avaliação pública de desempenho governamental.', 'jovens', 'família e cuidado', 'desigualdade', 'achado', 'indício', NULL, '3'), ('D07-TR-022-jov', 'Custo de vida, poder de compra e economia consta na lista de temas cuja menção deve ser evitada no momento.', 'jovens', 'família e cuidado', 'custo de vida', 'achado', 'indício', NULL, '5'), ('D07-TR-023-jov', 'Segurança pública consta na lista de temas cuja menção deve ser evitada no momento.', 'jovens', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '5'), ('D07-TR-025-jov', 'Educação pública consta na lista de temas cuja menção deve ser evitada no momento.', 'jovens', 'família e cuidado', 'educação', 'achado', 'indício', NULL, '5'), ('D07-TR-026-jov', 'Saúde pública consta na lista de temas cuja menção deve ser evitada no momento.', 'jovens', 'família e cuidado', 'saúde e sus', 'achado', 'indício', NULL, '5'), ('D07-TR-029-jov', 'Na Região Sul, segurança pública ocupa posição de peso mais alta na avaliação do que no conjunto do país.', 'jovens', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '6'), ('D07-TR-030-jov', 'Na Região Sul, saúde pública ocupa posição de peso mais baixa na avaliação do que no conjunto do país.', 'jovens', 'família e cuidado', 'saúde e sus', 'achado', 'indício', NULL, '6'), ('D07-TR-033-jov', 'Na Região Sudeste, saúde pública e programas sociais ocupam posição de peso mais alta na avaliação do que no conjunto do país.', 'jovens', 'família e cuidado', 'saúde e sus', 'achado', 'indício', NULL, '7'), ('D07-TR-036-jov', 'Na Região Centro-Oeste, saúde pública é a segunda área de maior peso na avaliação de desempenho governamental, posição muito acima da que ocupa no conjunto do país.', 'jovens', 'família e cuidado', 'saúde e sus', 'achado', 'indício', NULL, '8'), ('D07-TR-040-jov', 'Na Região Nordeste, educação pública é a área de maior peso na avaliação de desempenho governamental, à frente de custo de vida.', 'jovens', 'família e cuidado', 'educação', 'achado', 'indício', NULL, '9'), ('D07-TR-041-jov', 'Na Região Nordeste, programas de habitação e moradia ocupam a quarta posição em peso na avaliação, com participação quase o dobro da observada no conjunto do país.', 'jovens', 'família e cuidado', 'moradia e cidade', 'achado', 'indício', NULL, '9'), ('D07-TR-046-jov', 'Na Região Norte, segurança pública ocupa posição de peso mais alta na avaliação do que no conjunto do país.', 'jovens', 'família e cuidado', 'segurança pública', 'achado', 'indício', NULL, '10'), ('D07-TR-047-jov', 'Na Região Norte, saúde pública ocupa posição de peso mais baixa na avaliação do que no conjunto do país.', 'jovens', 'família e cuidado', 'saúde e sus', 'achado', 'indício', NULL, '10'), ('D01-TR-057-jov', 'A narrativa de "governo que cuida" soa paternalista: o problema percebido não é falta de cuidado, é falta de lei aplicada com rigor.', 'jovens', 'família e cuidado', 'segurança pública', 'afasta', NULL, NULL, '25'), ('D04-TR-228-fam', 'Infantilizar afasta: esses jovens podem ter trabalho, família e filhos, e precisam ser reconhecidos como jovens sem serem tratados como adolescentes.', 'jovens', 'família e cuidado', 'condição juvenil', 'afasta', NULL, NULL, '40'), ('D04-TR-229-fam', 'Cobrar que o jovem resolva sozinho o que é estrutural afasta: ele precisa de informação simples, proteção efetiva e caminhos claros.', 'jovens', 'família e cuidado', 'autonomia e amparo', 'afasta', NULL, NULL, '40'), ('D04-TR-230-fam', 'Convocação abstrata afasta: a comunicação precisa começar nos temas que já organizam a rotina, estudo, transporte, consumo, primeiro emprego, escala, família e segurança.', 'jovens', 'família e cuidado', 'comunicação e linguagem', 'afasta', NULL, NULL, '40'), ('D06-TR-044', 'Comunicação que fala de família sem reconhecer essa concretude tende a soar moralista ou distante.', 'jovens', 'família e cuidado', 'comunicação e linguagem', 'afasta', NULL, NULL, '12'), ('D06-TR-102', 'Tem força emocional, mas também risco de soar como uso político da família quando fica moralista ou genérica.', 'jovens', 'família e cuidado', 'família e maternidade', 'afasta', NULL, NULL, '35'), ('D06-TR-162-fam', 'Falar com um "jovem" abstrato afasta: este público se mede por responsabilidade, tempo curto, dinheiro, família e futuro, e precisa ser tratado como jovem adulto.', 'jovens', 'família e cuidado', 'comunicação e linguagem', 'afasta', NULL, NULL, '10'), ('D06-TR-163-fam', 'Reproduzir estereótipos de jovem irresponsável, geração que não quer trabalhar ou gente sem experiência para opinar afasta: a juventude vira marca de suspeita e gera irritação.', 'jovens', 'família e cuidado', 'etarismo', 'afasta', NULL, NULL, '11'), ('D06-TR-165-fam', 'Mensagens sobre futuro que soam apenas inspiracionais afastam: futuro crível mostra caminho, condição e proteção.', 'jovens', 'família e cuidado', 'futuro possível', 'afasta', NULL, NULL, '13'), ('D06-TR-166', 'Tratar proteção como valor abstrato afasta as mulheres jovens: proteção é respeito, segurança, renda, tempo, cuidado e liberdade para circular sem medo.', 'jovens', 'família e cuidado', 'violência contra a mulher', 'afasta', NULL, NULL, '14'), ('D06-TR-167-fam', 'Reduzir a comunicação com jovens a "linguagem jovem" afasta: o que aproxima é reconhecer uma juventude encurtada por trabalho, família, medo e necessidade de construir futuro cedo.', 'jovens', 'família e cuidado', 'comunicação e linguagem', 'afasta', NULL, NULL, '15'), ('D06-TR-045', 'A família reorganiza a vida do jovem em torno de cuidado, provisão, expectativa e medo de falhar.', 'jovens', 'família e cuidado', 'família e maternidade', 'contexto', NULL, NULL, '12'), ('D06-TR-049', 'Há projeção do próprio futuro a partir da rotina do filho, com estágio, escola, cuidado e custo precisando caber juntos.', 'jovens', 'família e cuidado', 'educação', 'contexto', NULL, NULL, '13'), ('D01-TR-054-jov', 'Cuidar é proteger a vida concreta, mas também devolver às mulheres o direito de fazer planos.', 'jovens', 'família e cuidado', 'segurança pública', 'funciona', NULL, NULL, '23'), ('D01-TR-060-jov', 'Não é sobre anunciar mais uma lei, é sobre provar que alguma coisa mudou.', 'jovens', 'família e cuidado', 'segurança pública', 'funciona', NULL, NULL, '25'), ('D01-TR-065-jov', 'O cuidado não pode depender só da força individual da mãe: a rede de assistência deve cuidar de quem cuida, e a imagem da "mãe heroica que dá conta de tudo sozinha" precisa ser quebrada.', 'jovens', 'família e cuidado', 'rede de apoio', 'funciona', NULL, NULL, '26'), ('D01-TR-066-jov', 'Responder à violência com caminho prático, não com campanha genérica; a proteção digital dos filhos é a porta de entrada mais aberta desse território, e feminicídio é lugar delicado de diálogo, pois não há sensação de segurança com as soluções disponíveis.', 'jovens', 'família e cuidado', 'proteção da infância', 'funciona', NULL, NULL, '26'), ('D01-TR-067-jov', 'Ancorar o sonho na segurança: quando o cuidado funciona, sobra espaço para estudar, descansar e sonhar, o direito de sonhar além da sobrevivência.', 'jovens', 'família e cuidado', 'rede de apoio', 'funciona', NULL, NULL, '26'), ('D01-TR-124', 'A entrada mais potente é a família concreta: mãe, filho, irmã, esposa, casa, escola, saúde, dinheiro, internet e volta segura para casa.', 'jovens', 'família e cuidado', 'família e maternidade', 'funciona', NULL, NULL, '47'), ('D04-TR-018-fam', 'O conteúdo aproxima mais quando vem em formato curto e real: relato, bastidor, tutorial, comparação, antes e depois e dica prática.', 'jovens', 'família e cuidado', 'comunicação e linguagem', 'funciona', NULL, NULL, '10'), ('D04-TR-048-fam', 'Relatos, tutoriais, bastidores, antes e depois e linguagem direta aproximam mais do que propaganda.', 'jovens', 'família e cuidado', 'comunicação e linguagem', 'funciona', NULL, NULL, '14'), ('D04-TR-190-fam', 'Comunicar com concretude, linguagem simples, prova verificável e formatos próximos: relato, bastidor, tutorial, antes e depois, humor e checagem.', 'jovens', 'família e cuidado', 'comunicação e linguagem', 'funciona', NULL, NULL, '39'), ('D04-TR-199-fam', 'Transformar políticas em condição de vida melhor: dinheiro, trabalho e engajamento precisam aparecer como suporte concreto, como pagar o básico, sair da dívida, trabalhar com dignidade, entender direitos, checar informações e cobrar resultados.', 'jovens', 'família e cuidado', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D04-TR-200-fam', 'Partir da vida real, não da convocação abstrata: a comunicação deve começar nos temas que já organizam a rotina, como estudo, transporte, consumo, primeiro emprego, escala, Pix, taxa das blusinhas, família, segurança, voto e futuro.', 'jovens', 'família e cuidado', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D04-TR-201-fam', 'Dar competência sem transferir responsabilidade: o jovem não precisa ser cobrado a resolver sozinho o que é estrutural, e sim de informação simples, proteção efetiva e caminhos claros para viver melhor, decidir com mais segurança e voltar a vislumbrar futuro.', 'jovens', 'família e cuidado', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D06-TR-003-fam', 'As narrativas de maior força são as que partem da vida concreta.', 'jovens', 'família e cuidado', 'comunicação e linguagem', 'funciona', NULL, NULL, '7'), ('D06-TR-043', 'Família não deve ser tratada como valor abstrato: para esse público, família é tempo, dinheiro, cuidado, escola, segurança, descanso e presença.', 'jovens', 'família e cuidado', 'família e maternidade', 'funciona', NULL, NULL, '12'), ('D06-TR-046', 'Para gerar identificação, a comunicação deve tratar família como experiência concreta e não como valor abstrato: tempo, dinheiro, cuidado, escola, segurança, descanso e presença.', 'jovens', 'família e cuidado', 'família e maternidade', 'funciona', NULL, NULL, '12'), ('D06-TR-103', 'A entrada mais potente é a família concreta: mãe, filho, irmã, esposa, casa, escola, saúde, dinheiro, internet e volta segura para casa. O ponto estratégico é deslocar família de uma disputa moral para uma agenda de proteção material e cotidiana.', 'jovens', 'família e cuidado', 'família e maternidade', 'funciona', NULL, NULL, '35'), ('D06-TR-111', 'Em públicos mais conservadores, falar de feminicídio diretamente pode soar progressista demais, mas falar da mãe, irmã, esposa ou filha que precisa voltar em segurança tende a aproximar.', 'jovens', 'família e cuidado', 'violência contra a mulher', 'funciona', NULL, NULL, '36'), ('D06-TR-112', 'A proteção da família é mais forte quando parte da experiência vivida e só depois chega à institucionalidade.', 'jovens', 'família e cuidado', 'violência contra a mulher', 'funciona', NULL, NULL, '36'), ('D06-TR-142-fam', 'Responsabilização é menos um território emocional e mais uma chave de tradução: ganha força quando explica por que o voto para Legislativo, Senado e Congresso afeta salário, escala, direitos, internet, transporte, segurança e programas.', 'jovens', 'família e cuidado', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D06-TR-144-fam', 'Quando a comunicação traduz quem aprova, quem bloqueia, quem executa e quem responde, a política deixa de parecer um bloco distante.', 'jovens', 'família e cuidado', 'comunicação e linguagem', 'funciona', NULL, NULL, '40'), ('D06-TR-155-fam', 'Proteção do trabalhador, dinheiro no bolso e proteção da família são os territórios de maior lastro espontâneo — já estão na vida dos jovens antes da política aparecer, por isso devem funcionar como portas de entrada principais.', 'jovens', 'família e cuidado', 'comunicação e linguagem', 'funciona', NULL, NULL, '42'), ('D06-TR-156-fam', 'Brasil Core e Engajamento Cívico têm potencial, mas precisam de prova: Brasil precisa aparecer como cultura vivida e soberania concreta; Engajamento precisa mostrar onde a voz jovem produz efeito.', 'jovens', 'família e cuidado', 'comunicação e linguagem', 'funciona', NULL, NULL, '42'), ('D06-TR-158-fam', 'Responsabilização e Senado é a principal ponte pedagógica: não mobiliza sozinho, mas ajuda a transformar temas concretos em escolha eleitoral, mostrando quem aprova, quem trava, quem amplia e quem ameaça.', 'jovens', 'família e cuidado', 'comunicação e linguagem', 'funciona', NULL, NULL, '42'), ('D06-TR-067', '“Ser jovem e ser mulher tem muito essa questão do medo ao seu lado.”', 'jovens', 'família e cuidado', 'violência contra a mulher', 'verbatim', NULL, NULL, '14'), ('D06-TR-068', '“Tem evento que acaba tarde da noite. Não dá para voltar sozinha. Tem que gastar com Uber ou pedir para o marido buscar.”', 'jovens', 'família e cuidado', 'moradia e cidade', 'verbatim', NULL, NULL, '14'), ('D06-TR-069', '“A gente é mulher e nova, então a gente é alvo de muitas coisas. Acho que ser roubada é o menos pior.”', 'jovens', 'família e cuidado', 'segurança pública', 'verbatim', NULL, NULL, '14'), ('D06-TR-105', '“Com quem ele vai ficar? Como vai ser essa nova rotina para ele?”', 'jovens', 'família e cuidado', 'gênero e trabalho', 'verbatim', NULL, NULL, '35'), ('D06-TR-106', '“A questão da família é mais apoio mesmo. Todo mundo sempre me incentivando.”', 'jovens', 'família e cuidado', 'família e maternidade', 'verbatim', NULL, NULL, '35'), ('D06-TR-107', '“Essa escala afasta a gente um pouco da família. Chega em casa cansado, não dá a devida atenção para a esposa, para os filhos.”', 'jovens', 'família e cuidado', 'jornada de trabalho', 'verbatim', NULL, NULL, '35'), ('D06-TR-114', '“Segurança hoje em dia, sendo jovem, sendo mulher, é o fator principal.”', 'jovens', 'família e cuidado', 'violência contra a mulher', 'verbatim', NULL, NULL, '36');
